Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <algorithm>
#include <iostream>
#include <cstring>
#include <cstdio>
#include <vector>
#include <cctype>

#define File(a) freopen(a".in", "r", stdin), freopen(a".out", "w", stdout)

using std::pair;
using std::make_pair;

#define pii pair<int, int>
#define mp make_pair

using ll = long long;
const int inf = 1e9;
const ll infll = 0ll + 1e18;

#define int long long
const int mod1 = 998244353;
const int mod2 = 1e9 + 7;
const int Base = 1000000;

int n, tot, sum[15], ans;
std::vector <int> vec[15];

inline void dfs1(int, int);
inline void dfs2(int);

signed main(void) {
  std::cin >> n;
  dfs1(0, 0);
  for (int i = 0; i <= 7; i++)
    std::sort(vec[i].begin(), vec[i].end());
  tot = 0;
  for (int i = 1; i <= 9; i++) dfs2(i);
  std::cout << ans << std::endl;
  return 0;
}

inline void dfs1(int k, int num) {
  if (k == 7) return ;
  tot ++;
  int back = ((tot - num) % mod1 + mod1) % mod1;
  vec[k].emplace_back(back);
  sum[k] = (sum[k] + back) % mod2;
  for (int i = 0; i <= 9; i ++)
    dfs1(k + 1, num * 10 + i);
}
inline void dfs2(int x) {
  if (x > n) return ;
  if (x * Base + Base - 1 <= n && x * Base * 10 > n) {
    int now = tot;
    for (int i = 0, mul = 1; i <= 6; i++, mul *= 10) {
      int sz = vec[i].size();
      int dif = ((now - x * mul) % mod1 + mod1) % mod1;
      // std::cout << dif << std::endl;
      int pos = std::lower_bound(vec[i].begin(), vec[i].end(), mod1 - dif) - vec[i].begin();
      ans = (ans + dif * sz + sum[i]) % mod2;
      ans = (ans - mod1 * (sz - pos) % mod2 + mod2) % mod2;
      tot += sz;
    }
    return ;
  }
  tot ++;
  ans = (ans + ((tot - x) % mod1 + mod1) % mod1) % mod2;
  for (int i = 0; i <= 9; i ++) dfs2(x * 10 + i);
}
